package pe.edu.upeu.casaonada.notificacion.service;
import pe.edu.upeu.casaonada.notificacion.domain.*; import pe.edu.upeu.casaonada.notificacion.dto.*; import pe.edu.upeu.casaonada.notificacion.exception.ResourceNotFoundException; import pe.edu.upeu.casaonada.notificacion.mapper.NotificacionMapper; import pe.edu.upeu.casaonada.notificacion.repository.NotificacionRepository; import org.springframework.stereotype.Service; import org.springframework.transaction.annotation.Transactional; import java.util.*;
@Service public class NotificacionService { private final NotificacionRepository repo; private final NotificacionMapper mapper; public NotificacionService(NotificacionRepository r,NotificacionMapper m){repo=r;mapper=m;} @Transactional public NotificacionResponse crear(NotificacionRequest r){return mapper.toResponse(repo.save(mapper.toEntity(r)));} @Transactional(readOnly=true) public List<NotificacionResponse> listar(){return repo.findAll().stream().map(mapper::toResponse).toList();} @Transactional(readOnly=true) public NotificacionResponse buscar(Long id){return mapper.toResponse(entidad(id));} @Transactional public NotificacionResponse marcarLeida(Long id){Notificacion n=entidad(id);n.setEstado(EstadoNotificacion.LEIDA);return mapper.toResponse(repo.save(n));} private Notificacion entidad(Long id){return repo.findById(id).orElseThrow(()->new ResourceNotFoundException("Notificación no encontrada: "+id));} }
